// Mastodon logo + student initials + institution name ROM
// 512x128 pixels, 4-color palette.
//
// Address: {y[6:0], x[8:0]} = 16-bit, addr = y*512 + x.
// Both strides are powers of two — no stride gaps.
//
// Layout (left to right):
//   x=  0..127 : Mastodon mascot 128x128 (4-color, 84.8% accuracy)
//   x=128..129 : grey vertical separator
//   x=130..321 : student initials panel (192px, 3 per row x 4 rows):
//                  Row 0: C.A  B.F  A.V
//                  Row 1: V.V  H.M  E.O
//                  Row 2: E.R  S.Q  S.N
//                  Row 3: M.H  A.W  G.W
//   x=322..323 : grey vertical separator
//   x=324..511 : institution name (centred, black, 8px font):
//                  PURDUE FORT WAYNE
//                  DEPARTMENT OF
//                  ELECTRICAL AND
//                  COMPUTER ENGINEERING
//
// Palette:
//   idx 0: 8'hFC  white   (default)
//   idx 1: 8'h00  black   (mastodon outline + all text)
//   idx 2: 8'hA8  grey    (separators + mastodon body)
//   idx 3: 8'hE0  orange  (mastodon accent)
`default_nettype none

module mastodon_rom_compress (
    input  wire [8:0] x,
    input  wire [6:0] y,
    output reg  [7:0] pixel
);

    reg [1:0] idx;

    always @(*) begin
        case ({y, x})  // 16-bit: addr = y*512 + x
            16'd    8: idx = 2'd2;
            16'd    9: idx = 2'd2;
            16'd   10: idx = 2'd2;
            16'd   11: idx = 2'd2;
            16'd   12: idx = 2'd2;
            16'd   13: idx = 2'd2;
            16'd   14: idx = 2'd2;
            16'd   15: idx = 2'd2;
            16'd   16: idx = 2'd2;
